package app.n_zik.android.listentogether

import android.content.Intent
import android.net.Uri
import android.os.Bundle
import java.util.Locale

internal const val INVITE_ROOM_CODE_KEY = "listen_together_invite_code"
private const val PENDING_INVITE_URI_KEY = "pending_listen_together_invite_uri"

/** Parses only the invitation format generated by Listen Together. */
internal fun parseListenTogetherInvite(uri: Uri): String? {
    if (!uri.isHierarchical ||
        !uri.scheme.equals("https", ignoreCase = true) ||
        !uri.host.equals("metrolist.cc", ignoreCase = true) ||
        uri.userInfo != null || uri.port != -1 || uri.path != "/listen"
    ) return null

    val codes = uri.getQueryParameters("code")
    val code = codes.singleOrNull() ?: return null
    return code.takeIf { it.matches(Regex("[A-Za-z0-9]{8}")) }?.uppercase(Locale.ROOT)
}

/** Returns a link only for supported external intent actions. */
internal fun listenTogetherInviteUri(intent: Intent): Uri? =
    when (intent.action) {
        Intent.ACTION_VIEW -> intent.data
        Intent.ACTION_SEND -> intent.getStringExtra(Intent.EXTRA_TEXT)?.trim()?.let(Uri::parse)
        else -> null
    }?.takeIf { parseListenTogetherInvite(it) != null }

/** Keeps invitation delivery out of the launcher shortcut's return-to-home effect. */
internal fun inviteAwareShortcutAction(intent: Intent): String? =
    intent.action.takeUnless { listenTogetherInviteUri(intent) != null }

/** Restores pending delivery without replaying the launch intent after consumption. */
internal fun restoreListenTogetherInvite(intent: Intent, savedState: Bundle?): Uri? =
    if (savedState == null) listenTogetherInviteUri(intent)
    else savedState.getString(PENDING_INVITE_URI_KEY)?.let(Uri::parse)
        ?.takeIf { parseListenTogetherInvite(it) != null }

/** Saves a pending invitation across recreation, including the consumed null state. */
internal fun saveListenTogetherInvite(savedState: Bundle, pendingUri: Uri?) {
    savedState.putString(
        PENDING_INVITE_URI_KEY,
        pendingUri?.takeIf { parseListenTogetherInvite(it) != null }?.toString(),
    )
}
